style.css:
@-moz-document domain("youtube.com") {
/* ====== GENERAL ====== */
    body {
        background: #181818 !important;
        font-family: Arial, sans-serif !important;
        color: #eee !important;
    }

    /* Links azules estilo clásico */
    a {
        color: #4da6ff !important;
        text-decoration: none !important;
    }
    a:hover {
        text-decoration: underline !important;
    }

    /* ====== BARRA SUPERIOR ====== */
    #masthead-container, ytd-masthead {
        background: #cc181e !important; /* rojo clásico */
        box-shadow: none !important;
    }
    #logo-icon {
        display: none !important;
    }
    #logo {
        font-size: 24px !important;
        font-weight: bold !important;
        color: white !important;
        text-decoration: none !important;
    }

    /* ====== BARRA DE BÚSQUEDA ====== */
    #center.ytd-masthead,
    #search-form,
    ytd-searchbox {
        background: none !important;
    }

    /* Caja de texto */
    input#search {
        border-radius: 0 !important;
        border: 1px solid #444 !important;
        background: #121212 !important;
        color: #eee !important;
        font-size: 14px !important;
        padding: 4px 6px !important;
        box-shadow: none !important;
    }

    /* Botón de búsqueda */
    button#search-icon-legacy {
        border-radius: 0 !important;
        border: 1px solid #444 !important;
        background: #2a2a2a !important;
        margin-left: -1px !important;
        padding: 4px 12px !important;
        box-shadow: none !important;
        color: #eee !important;
    }
    button#search-icon-legacy:hover {
        background: #3a3a3a !important;
    }

    /* Ocultar micrófono (no existía en el diseño retro) */
    ytd-microphone-renderer {
        display: none !important;
    }

    /* ====== BOTONES ====== */
    ytd-button-renderer button,
    ytd-topbar-menu-button-renderer button,
    tp-yt-paper-button,
    button {
        border-radius: 0 !important;
        background: #2a2a2a !important;
        border: 1px solid #444 !important;
        color: #ddd !important;
        font-size: 12px !important;
        padding: 4px 8px !important;
        box-shadow: none !important;
    }
    ytd-button-renderer button:hover {
        background: #3a3a3a !important;
    }

    /* ====== MINIATURAS ====== */
    ytd-thumbnail img {
        border-radius: 0 !important;
    }

    /* ====== TÍTULOS DE VIDEOS ====== */
    a#video-title,
    h3.ytd-video-renderer a {
        font-size: 14px !important;
        font-weight: bold !important;
        color: #4da6ff !important;
    }

    /* ====== SIDEBAR ====== */
    ytd-guide-renderer,
    ytd-mini-guide-renderer {
        background: #202020 !important;
    }
    ytd-guide-section-renderer,
    ytd-guide-entry-renderer {
        background: #2a2a2a !important;
        border: 1px solid #444 !important;
        margin: 2px 0 !important;
        padding: 4px !important;
    }

    /* ====== RESULTADOS DE BÚSQUEDA ====== */
    ytd-video-renderer,
    ytd-channel-renderer {
        background: #202020 !important;
        border: 1px solid #333 !important;
        margin-bottom: 8px !important;
        padding: 8px !important;
    }

    /* ====== PÁGINA DE VIDEO ====== */
    #above-the-fold,
    ytd-watch-flexy {
        background: #181818 !important;
    }

    /* Título de video grande */
    h1.title,
    yt-formatted-string.ytd-video-primary-info-renderer {
        font-size: 18px !important;
        font-weight: bold !important;
        color: #fff !important;
    }

    /* Botones de like/dislike clásicos */
    ytd-toggle-button-renderer {
        border: 1px solid #444 !important;
        background: #2a2a2a !important;
        margin-right: 4px !important;
    }

    /* ====== COMENTARIOS ====== */
    ytd-comment-renderer {
        border-bottom: 1px solid #333 !important;
        padding: 8px 0 !important;
    }
    #author-text {
        color: #4da6ff !important;
        font-weight: bold !important;
    }
    #content-text {
        font-size: 13px !important;
        color: #ddd !important;
    }

    /* ====== FOOTER ====== */
    #footer {
        background: #202020 !important;
        font-size: 12px !important;
        text-align: center !important;
        padding: 10px !important;
        color: #aaa !important;
    }
}
